  const n = BigInt(numerator);
  const d = BigInt(denominator);
  if (d === 0n) throw new Error('Denominator cannot be zero');
  if (n === 0n) return { numerator: '0', denominator: '1' };

  const gcd = (a, b) => (b === 0n ? a : gcd(b, a % b));
  const g = gcd(a < 0n ? -a : a, d);
  const num = (n < 0n ? -n : n) / g;
  const den = d / g;

  return { numerator: num.toString(), denominator: den.toString() };
}

